package com.crm.fees;
import com.crm.fees.repository.FeeReportRepository;import org.junit.jupiter.api.*;import org.springframework.data.jpa.repository.Query;import org.springframework.data.domain.Pageable;import org.springframework.jdbc.datasource.SingleConnectionDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;import java.sql.*;import java.time.LocalDate;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Synthetic in-memory H2 tables; no migrations, JPA projections or MySQL execution. */
class FeeReportFixtureTest {
 Connection connection;JdbcTemplate jdbc;NamedParameterJdbcTemplate named;
 @BeforeEach void setup()throws Exception{connection=DriverManager.getConnection("jdbc:h2:mem:fees3e_"+UUID.randomUUID()+";MODE=MySQL");var source=new SingleConnectionDataSource(connection,true);jdbc=new JdbcTemplate(source);named=new NamedParameterJdbcTemplate(source);
 jdbc.execute("create table fees(offering_id bigint,service_name varchar(255),customer_id varchar(50),currency varchar(3),work_date date,exact_hours decimal(8,2),amount decimal(12,2))");
 jdbc.execute("create table fee_offerings(id bigint,title varchar(255),customer_id varchar(50),currency varchar(3))");jdbc.execute("create table fee_time_entries(offering_id bigint,work_date date,cancelled boolean,fee_id bigint,hours decimal(8,2),amount decimal(12,2))");
 jdbc.update("insert into fee_offerings values(7,'Consulting','202','TND'),(8,'Other','203','EUR')");
 jdbc.update("insert into fees values(7,'Consulting','202','TND','2026-01-01',2.50,30.85),(8,'Other','203','EUR','2026-01-31',1,20),(null,'Legacy','202',null,'2026-01-20',null,100),(7,'Outside','202','TND','2026-02-01',1,12.34)");
 jdbc.update("insert into fee_time_entries values(7,'2026-01-01',false,10,2.50,30.85),(7,'2026-01-02',false,null,1,12.34),(7,'2026-01-03',true,null,2,24.68),(8,'2026-01-31',false,null,1,20),(7,'2025-12-31',false,null,1,12.34)");}
 @AfterEach void close()throws Exception{connection.close();}
 List<Map<String,Object>> rows(String method,String from,String to)throws Exception{String sql=FeeReportRepository.class.getMethod(method,LocalDate.class,LocalDate.class,Long.class,String.class,Pageable.class).getAnnotation(Query.class).value();var params=new HashMap<String,Object>();params.put("from",LocalDate.parse(from));params.put("to",LocalDate.parse(to));params.put("offering",null);params.put("customer",null);return named.queryForList(sql,params);}
 @Test void recordedGroupsKeepCurrenciesAndBothInclusiveBoundaries()throws Exception{var rows=rows("recorded","2026-01-01","2026-01-31");assertEquals(3,rows.size());assertEquals(3L,rows.stream().mapToLong(r->((Number)r.get("count")).longValue()).sum());assertTrue(rows.stream().anyMatch(r->"EUR".equals(r.get("currency"))&&new java.math.BigDecimal("20").compareTo((java.math.BigDecimal)r.get("amount"))==0));}
 @Test void unrecordedExcludesPostedAndCancelledWithoutDoubleCounting()throws Exception{var rows=rows("unrecorded","2026-01-01","2026-01-31");assertEquals(2,rows.size());var tnd=rows.stream().filter(r->"TND".equals(r.get("currency"))).findFirst().orElseThrow();assertEquals(1L,((Number)tnd.get("count")).longValue());assertEquals(0,new java.math.BigDecimal("12.34").compareTo((java.math.BigDecimal)tnd.get("amount")));}
 @Test void legacyUnknownCurrencyAndDurationStayNull()throws Exception{var legacy=rows("recorded","2026-01-01","2026-01-31").stream().filter(r->r.get("currency")==null).findFirst().orElseThrow();assertNull(legacy.get("amount"));assertNull(legacy.get("hours"));}
 @Test void customerAndOfferingFiltersAreBoundInSql()throws Exception{String sql=FeeReportRepository.class.getMethod("recorded",LocalDate.class,LocalDate.class,Long.class,String.class,Pageable.class).getAnnotation(Query.class).value();var rows=named.queryForList(sql,Map.of("from",LocalDate.parse("2026-01-01"),"to",LocalDate.parse("2026-01-31"),"offering",7L,"customer","202"));assertEquals(1,rows.size());assertEquals("Consulting",rows.getFirst().get("title"));assertTrue(named.queryForList(sql,Map.of("from",LocalDate.parse("2026-01-01"),"to",LocalDate.parse("2026-01-31"),"offering",7L,"customer","203")).isEmpty());}
 @Test void emptyAndSingleDayPeriodsUseBoundJdbcDates()throws Exception{assertTrue(rows("recorded","2027-01-01","2027-01-31").isEmpty());assertTrue(rows("unrecorded","2027-01-01","2027-01-31").isEmpty());assertEquals(1,rows("recorded","2026-01-01","2026-01-01").size());assertEquals(0,rows("unrecorded","2026-01-01","2026-01-01").size());}
}
